function resolveResponseReviews(events){const latest=events.reduce((n,e)=>e.kind==='assistant'&&['act','ask','done'].includes(e.value?.status)&&Number.isInteger(e.value.step)?Math.max(n,e.value.step):n,0);for(const row of $('#ag-log').querySelectorAll('[data-kind="protocol_error"][data-review-step]')){const step=Number(row.dataset.reviewStep);if(!Number.isInteger(step)||step>=latest||row.classList.contains('ag-resolved-review'))continue;row.classList.add('ag-resolved-review');row.querySelector('strong').textContent='Response review · resolved';const note=make('p','A later planning response was accepted. This earlier feedback is retained for reference.');row.querySelector('strong').after(note);let details=row.querySelector('details');if(!details){details=make('details');details.append(make('summary','Original response feedback'));const pre=row.querySelector('pre');if(pre)details.append(pre);row.append(details);}details.open=false;}}
