function reviewCommand(action,signal){const proposed=copy(action);return new Promise((resolve,reject)=>{if(signal?.aborted)return reject(new DOMException('Agent stopped.','AbortError'));if(commandReviewDialog.open)return reject(Error('An execution approval is already open'));const close=()=>{signal?.removeEventListener('abort',stop);commandReviewDialog.oncancel=null;commandReviewDialog.close();},stop=()=>{close();reject(new DOMException('Agent stopped before approving execution.','AbortError'));},decline=()=>{controller?.abort();if(!signal?.aborted)stop();};commandReviewDialog.querySelector('#ag-command-review-action').textContent=JSON.stringify(proposed,null,2);commandReviewDialog.querySelector('#ag-command-approve').onclick=()=>{if(signal?.aborted)return stop();close();resolve(proposed);};commandReviewDialog.querySelector('#ag-command-deny').onclick=decline;commandReviewDialog.oncancel=event=>{event.preventDefault();decline();};signal?.addEventListener('abort',stop,{once:true});status('Waiting for approval: '+proposed.tool+'. No request has been sent to the tool runtime.');commandReviewDialog.showModal();});}
const startChoice=make('dialog');startChoice.id='ag-start-choice';startChoice.className='sai-dialog';startChoice.setAttribute('aria-labelledby','ag-start-choice-title');startChoice.innerHTML='<h2 id="ag-start-choice-title">Review workspace takeover?</h2><p>Choose how this run may update the open project. Schema, reference and stale-edit checks always run.</p><p class="ag-note">This choice controls project takeovers. File and command tools still edit the configured runtime workspace immediately.</p><div class="ag-row"><button type="button" id="ag-start-reviewed" class="ag-primary" autofocus>Review before applying</button><button type="button" id="ag-start-direct">Apply without review</button><button type="button" id="ag-start-cancel">Cancel</button></div>';document.body.append(startChoice);startChoice.addEventListener('keydown',e=>e.stopPropagation());
function chooseTakeover(){if(startChoice.open)return Promise.resolve(null);return new Promise(resolve=>{const done=mode=>{startChoice.oncancel=null;startChoice.close();resolve(mode);};startChoice.querySelector('#ag-start-reviewed').onclick=()=>done('review');startChoice.querySelector('#ag-start-direct').onclick=()=>done('direct');startChoice.querySelector('#ag-start-cancel').onclick=()=>done(null);startChoice.oncancel=e=>{e.preventDefault();done(null);};startChoice.showModal();});}
const takeoverReview=make('dialog');takeoverReview.id='ag-project-review';takeoverReview.className='sai-dialog';takeoverReview.setAttribute('aria-labelledby','ag-project-review-title');takeoverReview.innerHTML='<h2 id="ag-project-review-title">Review project takeover</h2><p>The proposed document passed structural validation. Inspect it before applying; this does not certify functional correctness.</p><details><summary>Current document</summary><pre id="ag-project-review-before"></pre></details><details open><summary>Proposed document</summary><pre id="ag-project-review-after"></pre></details><div class="ag-row"><button type="button" id="ag-project-review-apply" class="ag-primary">Apply reviewed changes</button><button type="button" id="ag-project-review-reject">Reject changes</button><button type="button" id="ag-project-review-stop">Stop run</button></div>';document.body.append(takeoverReview);takeoverReview.addEventListener('keydown',e=>e.stopPropagation());
function reviewTakeover({before,next,signal}){return new Promise((resolve,reject)=>{if(signal?.aborted)return reject(new DOMException('Agent stopped.','AbortError'));if(takeoverReview.open)return reject(Error('A project review is already open.'));const finish=(accepted,error)=>{signal?.removeEventListener('abort',stop);takeoverReview.oncancel=null;takeoverReview.close();error?reject(error):resolve(accepted);},stop=()=>finish(false,new DOMException('Agent stopped.','AbortError'));takeoverReview.querySelector('#ag-project-review-before').textContent=JSON.stringify(before,null,2);takeoverReview.querySelector('#ag-project-review-after').textContent=JSON.stringify(next,null,2);takeoverReview.querySelector('#ag-project-review-apply').onclick=()=>finish(true);takeoverReview.querySelector('#ag-project-review-reject').onclick=()=>finish(false);takeoverReview.querySelector('#ag-project-review-stop').hidden=!signal;takeoverReview.querySelector('#ag-project-review-stop').onclick=()=>controller?.abort();takeoverReview.oncancel=e=>{e.preventDefault();finish(false);};signal?.addEventListener('abort',stop,{once:true});takeoverReview.showModal();});}


