const failurePanel=make('details');failurePanel.id='ag-failure-recovery';failurePanel.className='ag-details';failurePanel.hidden=true;const failureTitle=make('summary','Failure recovery'),failureBody=make('p'),failureSteps=make('ol'),failureNote=make('p'),failureDraft=make('button','Draft recovery follow-up'),failureExport=make('button','Export recovery report');failureDraft.id='ag-failure-draft';failureExport.id='ag-failure-export';failureDraft.type=failureExport.type='button';failurePanel.append(failureTitle,failureBody,failureSteps,failureNote,failureDraft,failureExport);$('#ag-cycle').after(failurePanel);let failureReport=null;
